+  border: 1px solid rgba(255, 114, 114, .32);
+  background: rgba(255, 114, 114, .12);
+}
+
+/* ------------------------------------------------------------------ rail */
+
+.rail {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 4px;
+  padding: 10px 0 12px;
+  border-right: 1px solid var(--c-line);
