+  z-index: 10;
+}
+
+.rail-btn {
+  width: 46px;
+  height: 48px;
+  display: grid;
+  place-items: center;
+  gap: 1px;
+  border-radius: var(--r-md);
+  color: var(--c-text-3);
+  transition: background var(--fast), color var(--fast);
+  position: relative;
+}
+
+.rail-btn svg {
+  width: 19px;
+  height: 19px;
+}
+
+.rail-btn span {
+  font-size: 9px;
+  letter-spacing: .02em;
+}
+
+.rail-btn:hover {
+  color: var(--c-text);
+  background: var(--c-panel-2);
+}
+
+.rail-btn.is-active {
+  color: var(--c-accent);
+  background: var(--c-accent-soft);
+}
+
+.rail-btn.is-active::before {
+  content: "";
+  position: absolute;
+  left: -10px;
+  top: 50%;
+  width: 3px;
+  height: 20px;
+  border-radius: 0 3px 3px 0;
+  background: var(--c-accent);
+  transform: translateY(-50%);
+}
+
+.rail-spacer {
+  flex: 1;
+}
+
+/* ------------------------------------------------------------------ sides */
+
+.side {
+  display: flex;
+  flex-direction: column;
+  min-height: 0;
+  border-color: var(--c-line);
+  background: var(--c-panel);
+  transition: opacity var(--base);
+}
+
+.side-left {
+  border-right: 1px solid var(--c-line);
+}
+
+.side-right {
+  border-left: 1px solid var(--c-line);
+}
+
+.side-head {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 10px;
+  padding: 12px 12px 10px 14px;
+  border-bottom: 1px solid var(--c-line-soft);
+  flex: none;
+}
+
+.side-head h2 {
+  font-size: 13px;
+  font-weight: 620;
+  letter-spacing: .01em;
+}
+
+.side-body {
+  flex: 1;
+  min-height: 0;
+  overflow-y: auto;
+  overflow-x: hidden;
+  padding: 12px;
+}
+
+.head-actions {
+  display: flex;
+  gap: 4px;
+}
+
+.icon-btn {
+  width: 26px;
+  height: 26px;
+  display: grid;
+  place-items: center;
+  border-radius: 7px;
+  color: var(--c-text-3);
+  font-size: 13px;
+  transition: background var(--fast), color var(--fast);
+}
+
+.icon-btn:hover {
+  background: var(--c-panel-3);
+  color: var(--c-text);
+}
+
+.icon-btn.danger:hover {
+  color: #ffd9d9;
+  background: rgba(255, 114, 114, .14);
+}
+
+/* ---------------------------------------------------------- canvas shell */
+
+.canvas-shell {
+  display: grid;
+  grid-template-rows: 38px 1fr;
+  min-width: 0;
+  min-height: 0;
+  background: var(--c-canvas);
+}
+
+.canvas-toolbar {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  padding: 0 14px;
+  border-bottom: 1px solid var(--c-line-soft);
+  background: rgba(13, 15, 20, .72);
+  font-size: 11px;
+  color: var(--c-text-3);
+}
+
+.hint-group {
+  display: flex;
+  align-items: center;
+  gap: 7px;
+  min-width: 0;
+  overflow: hidden;
+  white-space: nowrap;
+  text-overflow: ellipsis;
+}
+
+.hint-dot {
+  width: 5px;
+  height: 5px;
+  border-radius: 50%;
+  background: var(--c-accent);
+  flex: none;
+}
+
+.canvas-meta {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  flex: none;
+  font-variant-numeric: tabular-nums;
+}
+
+.dot-sep {
+  width: 3px;
+  height: 3px;
+  border-radius: 50%;
+  background: var(--c-line-strong);
+}
+
+/* ------------------------------------------------------------- statusbar */
+
+.statusbar {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  padding: 0 10px 0 8px;
+  border-top: 1px solid var(--c-line);
+  background: linear-gradient(180deg, #12151c, #0f1218);
+  z-index: 10;
+}
+
+.tab-strip {
+  display: flex;
+  align-items: center;
+  gap: 4px;
+  flex: 1;
+  min-width: 0;
+  overflow-x: auto;
+  scrollbar-width: none;
+}
+
+.tab-strip::-webkit-scrollbar {
+  display: none;
+}
+
+.page-tab {
+  display: inline-flex;
+  align-items: center;
+  gap: 7px;
+  height: 28px;
+  padding: 0 10px;
+  border: 1px solid transparent;
+  border-radius: var(--r-sm);
+  color: var(--c-text-3);
