+
+.page-tab:hover {
+  color: var(--c-text);
+  background: var(--c-panel-2);
+}
+
+.page-tab.is-active {
+  color: var(--c-text);
+  border-color: var(--c-line-strong);
+  background: var(--c-panel-3);
+}
+
+.page-tab .tab-shape {
+  width: 9px;
+  height: 9px;
+  border-radius: 3px;
+  background: var(--c-text-3);
+  flex: none;
+}
+
+.page-tab[data-shape="circle"] .tab-shape {
+  border-radius: 50%;
+}
+
+.page-tab[data-shape="pill"] .tab-shape {
+  border-radius: 4px / 6px;
+}
+
+.page-tab.is-active .tab-shape {
+  background: var(--c-accent);
+}
+
+.tab-add {
+  height: 28px;
+  padding: 0 11px;
+  border: 1px dashed var(--c-line-strong);
+  border-radius: var(--r-sm);
+  color: var(--c-text-3);
