+  outline: none;
+  transition: border-color var(--fast), background var(--fast);
+}
+
+.palette-search input:focus {
+  border-color: var(--c-accent-line);
+  background: var(--c-panel-2);
+}
+
+.palette-search svg {
+  position: absolute;
+  right: 9px;
+  top: 50%;
+  width: 14px;
+  height: 14px;
+  color: var(--c-text-3);
+  transform: translateY(-50%);
+  pointer-events: none;
+}
+
+.palette-group {
+  margin-bottom: 14px;
+}
+
+.palette-group-title {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  margin-bottom: 7px;
+  font-size: 10px;
+  font-weight: 650;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  color: var(--c-text-3);
+}
+
+.palette-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 7px;
+}
+
+.palette-item {
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  align-items: flex-start;
+  gap: 8px;
+  padding: 10px 10px 9px;
+  border: 1px solid var(--c-line);
+  border-radius: var(--r-md);
+  background: linear-gradient(170deg, var(--c-panel-2), var(--c-bg-2));
+  text-align: left;
+  cursor: grab;
+  transition: border-color var(--fast), transform var(--fast), box-shadow var(--fast), background var(--fast);
+}
+
+.palette-item:hover {
+  border-color: var(--c-accent-line);
+  transform: translateY(-1px);
+  box-shadow: var(--shadow-md);
+}
+
+.palette-item:active {
+  cursor: grabbing;
+  transform: translateY(0);
+}
+
+.palette-item.is-dragging {
+  opacity: .55;
+}
+
+.palette-preview {
+  width: 100%;
+  height: 34px;
+  display: grid;
+  place-items: center;
+  border-radius: var(--r-sm);
+  background: radial-gradient(120% 120% at 50% 0%, rgba(94, 200, 255, .08), transparent 70%), var(--c-canvas);
