+}
+
+.palette-preview span {
+  display: block;
+  background: linear-gradient(160deg, #3c4657, #2b3341);
+}
+
+.palette-item[data-item="ellipse"] .palette-preview span {
+  border-radius: 50%;
+  background: linear-gradient(160deg, var(--c-accent-2), var(--c-accent));
+}
+
+.palette-item[data-item="ring"] .palette-preview span {
+  border-radius: 50%;
+  background: none;
+  border: 2px solid var(--c-accent);
+}
+
+.palette-item[data-item="line"] .palette-preview span {
+  height: 2px;
+}
+
+.palette-item[data-item="metric"] .palette-preview span,
+.palette-item[data-item="title"] .palette-preview span,
+.palette-item[data-item="label"] .palette-preview span {
+  background: none;
+  color: var(--c-text-2);
+  font-size: 13px;
+  font-weight: 600;
+  letter-spacing: .02em;
+}
+
+.palette-item[data-item="metric"] .palette-preview span {
+  font-size: 17px;
+  color: var(--c-text);
+}
+
+.palette-item[data-item="card"] .palette-preview span {
+  width: 76%;
+  height: 24px;
+  border-radius: 7px;
+}
+
+.palette-item[data-item="grid"] .palette-preview span,
+.palette-item[data-item="stack"] .palette-preview span {
+  width: 76%;
+  height: 24px;
+  border-radius: 7px;
+  background:
+    linear-gradient(90deg, #333c4b 32%, transparent 32% 34%, #333c4b 34% 66%, transparent 66% 68%, #333c4b 68%),
+    transparent;
+}
+
+.palette-item[data-item="honeycomb"] .palette-preview span {
+  width: 26px;
+  height: 26px;
+  border-radius: 50%;
+  background:
+    radial-gradient(circle at 0 50%, #333c4b 0 4px, transparent 4px),
+    radial-gradient(circle at 50% 0, #333c4b 0 4px, transparent 4px),
+    radial-gradient(circle at 100% 50%, #333c4b 0 4px, transparent 4px),
+    radial-gradient(circle at 50% 100%, #333c4b 0 4px, transparent 4px);
+}
+
+.palette-item[data-item="button"] .palette-preview span,
+.palette-item[data-item="iconButton"] .palette-preview span {
