+}
+
+.palette-item[data-item="iconButton"] .palette-preview span {
+  width: 20px;
+  height: 20px;
+}
+
+.palette-item[data-item="progress"] .palette-preview span {
+  width: 76%;
+  height: 6px;
+  border-radius: 999px;
+  background: linear-gradient(90deg, var(--c-accent) 60%, #333c4b 60%);
+}
+
+.palette-item[data-item="chart"] .palette-preview span {
+  width: 76%;
+  height: 22px;
+  border-radius: 6px;
+  background:
+    linear-gradient(90deg, transparent 0 6%, #39424f 6% 14%, transparent 14% 18%, #46536a 18% 26%, transparent 26% 30%, #39424f 30% 38%, transparent 38% 42%, var(--c-select) 42% 50%, transparent 50% 54%, #46536a 54% 62%, transparent 62% 66%, #39424f 66% 74%, transparent 74%);
+}
+
+.palette-item[data-item="listRow"] .palette-preview span {
+  width: 84%;
+  height: 20px;
+  border-radius: 6px;
+  background: linear-gradient(90deg, #3b4557 0 18%, #2b3341 18% 100%);
+}
+
+.palette-name {
+  font-size: 11.5px;
+  font-weight: 580;
